rowdata.pyStepsJavaSource:
String proposedChildKey = com.pegarules.generated.pega_rules_default.GetInstanceHandle(tools.getParamValue("workPage"), tools);
String currentObjectKey = tools.getPrimaryPage().getString(".pzInsKey");
String currentCoverKey = tools.getPrimaryPage().getString(".pxCoverInsKey");

if (currentCoverKey.length() > 0) {

if (currentCoverKey.equals(proposedChildKey)) {
tools.getPrimaryPage().addMessage("CoverWouldContainItself");
}

String currentObjectClass = null;

String className = currentCoverKey.substring(0, currentCoverKey.indexOf(" "));
ClassDefinition cd = tools.getDatabase().getClassDef(className);
currentObjectClass = cd.getName();

ClipboardPage currentCoverPage = tools.createPage(currentObjectClass, "pyCurrentCover");
try {
currentCoverPage.putString("pzInsKey", currentCoverKey );
ClipboardPage lp = tools.createPage("Code-Pega-List", "");
lp.putString(".pyMaxRecords", "1");
while (currentCoverKey.length() > 0) {
	try {
                  lp.putString(".pyObjClass", currentObjectClass);
		int count = tools.getDatabase().executeRDB("select pxCoverInsKey as \"pxCoverInsKey\" from {Class:" + currentObjectClass + "} where pzInsKey = {pyCurrentCover.pzInsKey}", lp);
		if (count == 0) break;
		currentCoverKey = lp.getString(".pxResults(1).pxCoverInsKey");

		if (currentCoverKey.length() == 0) break;

		if (currentCoverKey.equals(proposedChildKey)) {
			tools.getPrimaryPage().addMessage("CoverWouldContainItself");
			break;
		}

		currentCoverPage.putString("pzInsKey", currentCoverKey);

		className = currentCoverKey.substring(0, currentCoverKey.indexOf(" "));
		cd = tools.getDatabase().getClassDef(className);
		currentObjectClass = cd.getName();
	} catch (DatabaseException ex) {
		tools.getPrimaryPage().addMessage(ex.getMessage());
		break;
	}

}
} finally {
currentCoverPage.removeFromClipboard();
}

}
